import 'package:flutter/material.dart';
class StatisticsCard extends StatelessWidget { final String label, value; final IconData icon; final Color color; const StatisticsCard({super.key, required this.label, required this.value, required this.icon, required this.color}); @override Widget build(BuildContext context) => Container(width: 130, padding: const EdgeInsets.all(14), decoration: BoxDecoration(color: color.withValues(alpha: .10), borderRadius: BorderRadius.circular(18)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(icon, color: color, size: 20), const Spacer(), Text(value, style: Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold)), Text(label, style: Theme.of(context).textTheme.labelMedium)])); }
